	// named, after checking the session's subject belongs there.
	SwitchPartition(context.Context, *SwitchPartitionRequest) (*SwitchPartitionResponse, error)
	// GetAccessPolicy reads the caller's partition's access policy.
	GetAccessPolicy(context.Context, *GetAccessPolicyRequest) (*GetAccessPolicyResponse, error)
	// SetAccessPolicy writes the caller's partition's access policy, which every
	// later login and handoff into the partition reads.
	SetAccessPolicy(context.Context, *SetAccessPolicyRequest) (*SetAccessPolicyResponse, error)
	// Switch active organization context
	SwitchContext(context.Context, *SwitchContextRequest) (*SwitchContextResponse, error)
	// Enable 2FA for authenticated user
	Configure2FA(context.Context, *Configure2FARequest) (*Configure2FAResponse, error)
	// Disable 2FA for authenticated user
	Delete2FA(context.Context, *Delete2FARequest) (*Delete2FAResponse, error)
	// Reset/disable 2FA configuration
	Reset2FA(context.Context, *Reset2FARequest) (*Reset2FAResponse, error)
	// Get user's 2FA configuration status
	Get2FAStatus(context.Context, *Get2FAStatusRequest) (*Get2FAStatusResponse, error)
	// Verify 2FA code during authentication
	Verify2FA(context.Context, *Verify2FARequest) (*Verify2FAResponse, error)
	// Check if device is trusted for 2FA bypass
	CheckTrustedDevice(context.Context, *CheckTrustedDeviceRequest) (*CheckTrustedDeviceResponse, error)
	// Check pending 2FA session state
	CheckPendingSession(context.Context, *CheckPendingSessionRequest) (*CheckPendingSessionResponse, error)
	// Lock out user after failed 2FA attempts
	LockoutUser(context.Context, *LockoutUserRequest) (*LockoutUserResponse, error)
	// Clear user lockout (admin/service operation)
	ClearLockout(context.Context, *ClearLockoutRequest) (*ClearLockoutResponse, error)
	// Check user lockout status
	GetLockoutStatus(context.Context, *GetLockoutStatusRequest) (*GetLockoutStatusResponse, error)
	// Initiate OAuth authentication flow
	AuthFlow(context.Context, *AuthFlowRequest) (*AuthFlowResponse, error)
	// Start OAuth authentication with provider
	AuthStart(context.Context, *AuthStartRequest) (*AuthStartResponse, error)
	// Create a browser session row server-side and return its session key.
	// Used by thin gateways (app.orbtr.io, login.hstles.com, custom-app.com)
	// that have no platform-DB access and therefore cannot call the local
	// platform/session backend directly. The gateway holds the cookie
	// ceremony (Set-Cookie with the returned session_key) but the row
	// itself lives on the auth node next to the users it FKs into.
	MintSession(context.Context, *MintSessionRequest) (*MintSessionResponse, error)
	// Create SSO handoff token
	Handover(context.Context, *HandoverRequest) (*HandoverResponse, error)
	// Verify and consume handoff token
	VerifyHandoff(context.Context, *VerifyHandoffRequest) (*VerifyHandoffResponse, error)
	// Initiate account recovery (sends email)
	InitiateRecovery(context.Context, *InitiateRecoveryRequest) (*InitiateRecoveryResponse, error)
	// Verify recovery code and return reset token
	VerifyRecoveryCode(context.Context, *VerifyRecoveryCodeRequest) (*VerifyRecoveryCodeResponse, error)
	// Generate new 2FA backup codes
	GenerateBackupCodes(context.Context, *GenerateBackupCodesRequest) (*GenerateBackupCodesResponse, error)
	// Complete OAuth flow and return user data (Design 1)
	CompleteOAuth(context.Context, *CompleteOAuthRequest) (*CompleteOAuthResponse, error)
	// Exchange OAuth authorization code for user profile on the auth node.
	// Gateways call this instead of running gothic.CompleteUserAuth() locally,
	// because OAuth secrets and goth providers only exist on the auth node.
	// Supports per-gateway callback URLs: the auth node creates a transient
	// goth provider with the caller's redirect_uri so the token exchange
	// matches the authorization request.
	ExchangeOAuthCode(context.Context, *ExchangeOAuthCodeRequest) (*ExchangeOAuthCodeResponse, error)
	// Check if 2FA is required for this user/device (Design 1)
	Check2FARequired(context.Context, *Check2FARequiredRequest) (*Check2FARequiredResponse, error)
