	CreateEmailToken(context.Context, *CreateEmailTokenRequest) (*CreateEmailTokenResponse, error)
	// Validate email magic link token
	ValidateEmailToken(context.Context, *ValidateEmailTokenRequest) (*ValidateEmailTokenResponse, error)
	// Delete (consume) email magic link token
	DeleteEmailToken(context.Context, *DeleteEmailTokenRequest) (*DeleteEmailTokenResponse, error)
	// Validate email login code (derived from token hash, zero additional storage)
	ValidateEmailCode(context.Context, *ValidateEmailCodeRequest) (*ValidateEmailCodeResponse, error)
	// Save OAuth provider linkage (tokens, provider user ID)
	SaveUserProvider(context.Context, *SaveUserProviderRequest) (*SaveUserProviderResponse, error)
	// List all linked SSO providers for the authenticated user
	ListUserProviders(context.Context, *ListUserProvidersRequest) (*ListUserProvidersResponse, error)
	// Enable or disable a specific SSO provider for login
	UpdateProviderStatus(context.Context, *UpdateProviderStatusRequest) (*UpdateProviderStatusResponse, error)
	// Issue new access + refresh token pair (after successful authentication)
	IssueToken(context.Context, *IssueTokenRequest) (*IssueTokenResponse, error)
	// Refresh access token using refresh token
	RefreshToken(context.Context, *RefreshTokenRequest) (*RefreshTokenResponse, error)
	// Revoke token (logout for JWT-based clients)
	RevokeToken(context.Context, *RevokeTokenRequest) (*RevokeTokenResponse, error)
	// Introspect token (validate and get claims - for resource servers)
	IntrospectToken(context.Context, *IntrospectTokenRequest) (*IntrospectTokenResponse, error)
	// Validate bearer token (for SecurityCore middleware)
	ValidateBearerToken(context.Context, *ValidateBearerTokenRequest) (*ValidateBearerTokenResponse, error)
	// Revoke all tokens for a user (logout from all devices)
	RevokeAllUserTokens(context.Context, *RevokeAllUserTokensRequest) (*RevokeAllUserTokensResponse, error)
	// VerifyState verifies an OAuth state token's HMAC signature, TTL, and origin
	// allowlist, and consumes the nonce (single-use replay protection). Gateways
	// call this RPC instead of verifying state locally so they never need to hold
	// the HMAC signing key. Centralising the nonce store on the auth node also
	// makes replay protection correct across horizontally-scaled gateway instances.
	VerifyState(context.Context, *VerifyStateRequest) (*VerifyStateResponse, error)
